 | 7%nat => exact (load_case_value_7 old f)
 | 8%nat => exact (load_case_value_8 old f)
 end.
Ltac finishUniversalVector vl old f Hvalue :=
 match goal with H : vector_value_eq ?v (load_update_value_31 _ _) |- _ =>
 let hf := fresh "FINAL_VECTOR" in
 assert (hf : v = loaded8 vl old f) by (
   exposeVectorGoal;
   rewrite <- load_all_updates_correct_fast;
   unfold load_all_updates; rewrite Hvalue; reflexivity);
 subst v
 end.
